{
  "findings": [
    {
      "ref": "[D345]",
      "area": "contact",
      "claim": "A parent reports that the LEGO Shop requires users to agree to Terms and Conditions before purchasing, and that the site provides phone numbers in multiple languages for support.",
      "stance": "neutral",
      "quote": "When you make a purchase through the LEGO Shop, you are placing the order with LEGO Brand Retail, Inc., 1001 Boylston Street, Boston, MA 02115. Any reference to \"we\", \"us\" or \"our\" means LEGO Brand Retail, Inc., and any reference to \"you\" or \"your\" means you as a customer. References to \"I\" and \"my\" in the theme questions do also mean you as a customer."
    },
    {
      "ref": "[D345]",
      "area": "money",
      "claim": "A parent reports that the LEGO Shop does not accept checks, money orders, or purchase orders as payment methods.",
      "stance": "neutral",
      "quote": "We apologize, but LEGO.com does not accept checks, money orders or purchase orders."
    },
    {
      "ref": "[D345]",
      "area": "data",
      "claim": "A parent reports that the LEGO Shop collects name, delivery address, billing address, phone number, email, LEGO ID, Insiders card number, payment details, and shares this data with third‑party service providers for shipping, fraud detection, and support.",
      "stance": "risk",
      "quote": "Unless otherwise explicitly opted into by you elsewhere (e.g. a cookie consent, Insiders or LEGO ID sign-up, newsletter sign-up), we only collect, use, store and share the following data from you in connection with your order on LEGO.com: Your name, delivery address, billing address and contact details like your phone number and email address If you have a LEGO ID, we also register your LEGO ID with the order and your order history If you are a Insiders member, we register your Insiders card number with the order and, if relevant, register Insiders points earned/rewards redeemed Your payment details, as appropriate, and we will share those with your chosen payment provider as well as our payment processing partner."
    },
    {
      "ref": "[D345]",
      "area": "age_gating",
      "claim": "A parent reports that the LEGO Shop does not sell products to children under 18 without parental consent, stating \"No, we do not sell products through the LEGO Shop for purchase by children. If you are under 18 years or do not possess full legal capacity, you may only use the LEGO Shop website under supervision and with the consent of your parent or guardian.\"",
      "stance": "mitigation",
      "quote": "No, we do not sell products through the LEGO Shop for purchase by children. If you are under 18 years or do not possess full legal capacity, you may only use the LEGO Shop website under supervision and with the consent of your parent or guardian."
    },
    {
      "ref": "[D345]",
      "area": "content",
      "claim": "A parent reports that the LEGO Shop’s Terms and Conditions include a clause stating that the site may cancel or reject orders for fraudulent activity or rule violations.",
      "stance": "risk",
      "quote": "We reserve the right to reject, hold, suspend or cancel any account or order that you place, or that you attempt to place with us, at our sole discretion. We want to make it possible for you (and as many others as possible) to use LEGO.com to place orders, so we have systems in place to minimize fraud and rules that everyone needs to follow in order to make things fair and to give everyone a chance to purchase products. We use fraud detection software to monitor LEGO.com and may cancel your user account or reject or cancel orders without notice to you if we determine that your account has been used to make fraudulent orders or you have tried to avoid the systems."
    }
  ]
}
